// Checks whether the pawn can perform the given attack action, plays it, and warns if the resulting animation group is not an attack group.
// @fnv 0x008935f0
bool Pawn::TryAttack(int action)
{
    if (this != _g_thePlayer && *g_011df6c4.Bool())
        return false;
    Weapon* weapon3 = process->weapon() ? process->weapon()->CallGetFlags() : 0;
    List* ammoA = process->ammo();
    int _perShot = 0;
    if (weapon3)
        _perShot = weapon3->GetAmmoPerShot();
    if (weapon3 && weapon3->GetCurrentAmmo(this))
    {
        if (!ammoA)
            return false;
        if (!ammoA->head())
            return false;
    }
    if (GetAnimAction() == 9 || GetAnimAction() == 17)
        return false;
    if (!canAttack())
        return false;
    if (!process->ready())
        return false;
    Anim* animationData8 = animation();
    if (!animationData8)
        return false;
    if (animationData8->sequence(4) && (animationData8->sequence(4)->group()->movement() == 1) != IsSneaking())
    {
        animationData8->BlendOut(4, false);
        return false;
    }
    bool allowReload = true;
    Package* currentPackage6 = GetCurrentProcess()->package();
    if (currentPackage6)
        allowReload = currentPackage6->GetPackType() != 8 && currentPackage6->GetPackType() != 16;
    if (allowReload && weapon3 && weapon3->GetCurrentAmmo(this))
    {
        int kChanceValue = process->chance(this);
        if (allowReload && !process->blocked() && ammoChance(kChanceValue) > 0.0 &&
            randomChance(ammoChance(kChanceValue)))
        {
            int reload7 = weapon3->GetReloadAnim(false) + 23;
            unsigned short reloadGroup2 = play(reload7, 0, 0, 0);
            if (GetType(reloadGroup2) == reload7)
                unk110 = reload7;
            return false;
        }
    }
    unsigned short played_ = play(action, 0, 0, 0);
    if (this == _g_thePlayer)
    {
        playerAttack(action);
        return true;
    }
    else if (isAttack(played_))
    {
        unk110 = action;
        return true;
    }
    else
    {
        int actual = GetType(played_);
        const char* actualName = actual == 255 ? "ANIM_GROUP_NONE" : DAT_011977d8[actual].name;
        const char* requestedName2 = action == 255 ? "ANIM_GROUP_NONE" : DAT_011977d8[action].name;
        FNV_Warning(
            "COMBAT: '%s' is queuing an attack with weapon '%s' with attack '%s' that has non-attack group '%s'.",
            hasName() ? name() : GetFullName(),
            weapon3 ? (weapon3->hasName() ? weapon3->name() : weapon3->fullName.get()) : "hand-to-hand", requestedName2,
            actualName);
    }
    return false;
}

