// Subtracts the ammo used by a shot from the process ammo count, reloads or unequips when empty, and returns the remaining count.
// @fnv 0x008a89a0
unsigned int ActorView::ConsumeAmmo(unsigned int shots)
{
    if (!process || !process->Weapon() || !process->Ammo())
        return 0;
    unsigned int remaining7 = process->Ammo()->Count();
    AmmoWeapon* weaponA = process->Weapon()->Item();
    AmmoWeapon* ammo_2 = process->Ammo()->Item();
    unsigned int used2 = shots != -1 ? shots : process->Shots();
    if (weaponA)
        used2 *= weaponA->GetAmmoPerShot();
    if (used2 > remaining7)
        used2 = remaining7;
    remaining7 = remaining7 - used2;
    process->Ammo()->SetCount(remaining7);
    if (CanRemove(weaponA))
        Remove(process->Ammo()->Item(), 0, used2, 0, 0, 0, 0, 0, 1, 0);
    if (!remaining7)
    {
        TimerView* timer = process->Timer();
        if (timer)
            timer->Reset(0.0f);
        if (process->Weapon() && process->Weapon()->Item()->Rating(process->Weapon()->Flag(6)) <= _gModifierZero &&
            Reload(process->Weapon()->Item(), IsSpecial(), process->Weapon()->Flag(2), 0))
        {
            remaining7 = process->Ammo()->Count();
        }
        else if (process->Weapon() && process->Ammo() && process->Weapon()->Item() == process->Ammo()->Item())
        {
            if (this == playerView)
            {
                playerView->GetBipedAnim(true)->RemoveBipedWeapon();
                playerView->GetBipedAnim(false)->RemoveBipedWeapon();
            }
            else if (Biped())
                Biped()->RemoveBipedWeapon();
            process->Clear(0, 0, 0);
            ClearWeapon(0);
        }
    }
    if (!remaining7)
    {
        Unequip(ammo_2, 1, 0, 0, 0, 1);
        CombatView* combat = Combat();
        if (combat)
            combat->Reset(0);
        if (IsPlayerTeammate())
            Notify(this, 7);
    }
    return remaining7;
}
