// Saves the actor's state fields, references, modifiers, permanent and override modifiers, and mover to the buffer, gated by save flags.
// @fnv 0x008aaf40
void SaveActor::AppendSaveLoadFormBuffer(SaveBuffer* buffer)
{
    SaveBase(buffer);
    float elapsed = saveClock.Time() - lastUpdate;
    buffer->SaveData(&elapsed, 4, 0);
    buffer->SaveData(&forceRun, 1, 0);
    buffer->SaveData(&forceSneak, 1, 0);
    buffer->SaveData(&process, 1, 0);
    buffer->SaveData(&alarm, 1, 0);
    buffer->SaveData(&timer, 4, 0);
    buffer->SaveData(&byte7d, 1, 0);
    buffer->SaveData(&attack, 4, 0);
    buffer->SaveData(&dead, 1, 0);
    buffer->SaveData(&forceQuest, 1, 0);
    buffer->SaveData(&buffered, 1, 0);
    buffer->SaveData(&resetAI, 1, 0);
    buffer->SaveData(&water, 1, 0);
    buffer->SaveData(&swimming, 1, 0);
    buffer->SaveData(&action, 4, 0);
    buffer->SaveData(&actionTimer, 4, 0);
    buffer->SaveData(&headTimer, 4, 0);
    buffer->SaveData(&onDeath, 1, 0);
    buffer->SaveData(&containerReset, 1, 0);
    buffer->SaveData(&teammate, 1, 0);
    buffer->SaveData(&emotion, 4, 0);
    buffer->SaveData(&emotionValue, 4, 0);
    buffer->SaveData(&block, 1, 0);
    buffer->SaveData(&reload, 1, 0);
    buffer->SaveData(&critical, 4, 0);
    buffer->SaveData(&theft, 1, 0);
    buffer->SaveData(&crimeStamp, 4, 0);
    buffer->SaveData(&ignoreCrime, 1, 0);
    buffer->SaveData(&minorCrime, 4, 0);
    buffer->SaveData(&majorCrime, 4, 0);
    buffer->SaveData(&lastSeen, 4, 0);
    buffer->SaveRef(killer, 0);
    buffer->SaveRef(templateBase, 0);
    buffer->SaveRef(ref70, 0);
    if (buffer->GetFlags().Test(0x400))
    {
        unsigned char state = GetState();
        buffer->SaveData(&state, 1, 0);
    }
    if (buffer->GetFlags().Test(0x80000))
    {
        int count = 0;
        unsigned int position = buffer->Reserve();
        SaveNode* node = &modifiers;
        while (node)
        {
            ValueReferencePair* entry = *node->Get();
            if (entry)
            {
                buffer->SaveRef(entry->reference, 0);
                buffer->SaveData(entry, 4, 0);
                count++;
            }
            node = node->Next();
        }
        buffer->Patch(count, position);
    }
    if (buffer->GetFlags().Test(0x800000))
        permanent.Save(buffer);
    if (buffer->GetFlags().Test(0x400000))
        overrides.Save(buffer);
    mover->Save(buffer);
}

