// Advances the actor's process by elapsed time (scaled by animation speed) and starts or stops the creature's movement sound based on movement state.
// @fnv 0x008b3230
void ActorSoundView::FUN_008b3230(float elapsed)
{
    MemScope scope(45, true, "D:\\_Fallout3\\Platforms\\Common\\Code\\Fallout\\AI\\Actor.cpp", 0x5d06);
    if (this != actorPlayer)
    {
        if (GetProcess())
        {
            float delta = elapsed;
            if (delta == 0.0 && !Paused())
            {
                if (actorVats.Mode() == 4 && this == vatsTarget)
                    delta = actorClock.Delta() * actorVats.Mult();
                else
                    delta = actorClock.Delta();
            }
            if (values.Get(51) > 0 && Animation())
                delta = Animation()->Speed() * delta;
            process->Update(delta);
        }
        if (IsCreature())
        {
            CreatureView* creature = Creature();
            signed char kind = creature ? creature->GetType() : -1;
            if (kind == 6 || kind == 7)
            {
                MovementSound* sound = creature ? creature->GetSoundByEditorID(10) : 0;
                if (sound && Node())
                {
                    bool moving = (CheckState() || Moving()) && !Suppress(false);
                    AudioPlaybackHandle handle;
                    Sounds()->Get(handle);
                    if (moving && !handle.Playing())
                    {
                        if (!handle.Valid())
                        {
                            handle.Assign(AudioSingleton()->Create(sound->GetPath(),
                                                                   SoundFlags(sound->GetData().flags) | 2, sound));
                            handle.SetFlag(1);
                            Sounds()->Set(handle);
                            handle.Attach(Node());
                        }
                        if (!handle.Playing())
                        {
                            handle.SetPosition(Position());
                            handle.Play(false);
                            Sounds()->Set(handle);
                        }
                    }
                    else if (!moving && handle.Playing())
                    {
                        handle.Stop();
                        Sounds()->Set(handle);
                    }
                    if (Suppress(false) && handle.Playing())
                    {
                        handle.Stop();
                        handle.Reset();
                        Sounds()->Set(handle);
                    }
                }
            }
        }
    }
}

